# Invert COMMAND_MAPPINGS to map each phrase to its action
PHRASE_TO_ACTION = {}
for action_key, phrases in COMMAND_MAPPINGS.items():
    for phrase in phrases:
        PHRASE_TO_ACTION[phrase] = ACTIONS[action_key]


def normalize_transcript(transcript):
    try:
        # Convert to lowercase
        transcript = transcript.lower()

        # Remove punctuation
        transcript = transcript.translate(str.maketrans("", "", string.punctuation))

        # Normalize whitespace (remove extra spaces)
        transcript = re.sub(r"\s+", " ", transcript).strip()

        return transcript
    except Exception as e:
        logging.error(f"Error executing normalize_transcript: {e}", exc_info=True)


def execute_command_fuzzy(transcript):
    try:
        # Normalize the transcript
        command = normalize_transcript(transcript)

        # Split the command at "and" and iterate through each part
        commands = command.split(" and ")

        for cmd in commands:
            # Strip any leading/trailing whitespace from each command
            cmd = cmd.strip()

            # Attempt to find a direct match
            action = PHRASE_TO_ACTION.get(cmd)

            # If no direct match is found, use fuzzy matching
            if not action:
                # Find the best fuzzy match (with a threshold of 80 for confidence)
                best_match, match_score = process.extractOne(
                    cmd, PHRASE_TO_ACTION.keys()
                )
                if (
                    match_score >= 60 and "computer" in transcript
                ):  # Adjust the threshold as needed
                    action = PHRASE_TO_ACTION.get(best_match)

            if action:
                action()  # Execute the corresponding action
                logging.info(f"{GREEN}Executing fuzzy command: {cmd}{RESET}")
                print(f"Executing command: {cmd}")
            else:
                print(f"No matching command found for: {cmd}")

        return True
    except Exception as e:
        logging.error(f"{RED}Error executing fuzzy command: {e}{RESET}", exc_info=True)

    return True

import time
from ctypes import cast, POINTER
from comtypes import CLSCTX_ALL
from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume

initial_volumes = {}  # Dictionary to store initial volumes for all devices


def get_current_volume(device):
    try:
        interface = device.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
        volume = cast(interface, POINTER(IAudioEndpointVolume))
        return volume.GetMasterVolumeLevelScalar()
    except Exception as e:
        print(f"Failed to get volume for device: {device.FriendlyName}, Error: {e}")
        return None


def set_volume(device, volume_level):
    try:
        interface = device.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None)
        volume = cast(interface, POINTER(IAudioEndpointVolume))
        volume.SetMasterVolumeLevelScalar(volume_level, None)
    except Exception as e:
        print(f"Failed to set volume for device: {device.FriendlyName}, Error: {e}")


def decrease_volume_all():
    global initial_volumes
    devices = AudioUtilities.GetAllDevices()
    for device in devices:
        if (
            device.state == 1 and "Speakers" in device.FriendlyName
        ):  # Only consider active speaker devices
            initial_volume = get_current_volume(device)
            if initial_volume is not None:
                initial_volumes[device.FriendlyName] = initial_volume
                print(
                    f"Decreasing volume for {device.FriendlyName} from {initial_volume * 100}% to 10%"
                )
                set_volume(device, 0.1)  # Set volume to 10%


def restore_volume_all():
    global initial_volumes
    devices = AudioUtilities.GetAllDevices()
    for device in devices:
        if device.state == 1 and device.FriendlyName in initial_volumes:
            print(
                f"Restoring volume for {device.FriendlyName} to {initial_volumes[device.FriendlyName] * 100}%"
            )
            set_volume(
                device, initial_volumes[device.FriendlyName]
            )  # Restore to initial volume


if __name__ == "__main__":
    decrease_volume_all()
    time.sleep(20)  # Simulate recording time
    restore_volume_all()
